/* kfast.c (agent n7-k15, 2026-10-09): production version 2 of the exact search of k15.c (CUT = 0, 4 or 12 only; rows that cannot matter are skipped by a mask;
 * same tree, same counts; generated by mkfast.py from k15.c, the search part rewritten).  Header of k15.c:
 * k15.c (agent n7-k15, 2026-10-09) - the statements F_S of PROOF_5899.md section 8.1 (search "tabs" of
 * pproto.c (a file of mine, not in this repository)) with additional cuts, as an exact search (mode run) and as a sampling
 * estimator of the same tree (mode est; Chen's stratified sampling, unbiased for the number of kept prefixes).
 *
 * Tree (identical to pproto.c mode tabs when CUT=0): a prefix A with r rows, d holes, t links of weight 4 is
 *   a violation  if t = S, LO < d <= G and r > P_S(d);
 *   kept (N)     if some level x, max(d, LO+1) <= x <= G, has r + P_{S-t}(x-d) > P_S(x)        -> weight-3 links
 *   kept (S)     if t < S and some such x has r + P_{S-t-1}(x-d) > P_S(x)                      -> weight-4 links
 * G = GTOP - 6 S.
 *
 * CUT bit 1 (Lemma FR, "full rows", proof in k15/PROOF_CUTS.md): a row with k classes has 1 - holes = k - 5 <= 1,
 *   = 1 only for k = 6, so rows(B) - holes(B) <= (number of full rows of B) <= Phi(A) for every sequence B whose
 *   classes avoid those of A, Phi(A) = number of 2-cycles (orbits of tau2 on entries, 840 of them, 6 classes each)
 *   none of whose classes is used by A.  Rule with the cut: the level x must also have r + (x-d) + Phi(A) > P_S(x).
 * CUT bit 2 (Lemma FR', packing): Phi(A) replaced by min(Phi(A), floor(c6(A) / 6)), c6(A) = number of unused
 *   classes that lie in at least one free 2-cycle (full rows of B are pairwise disjoint free 2-cycles).
 *
 * usage: k15 est S GTOP caps REPS seed      |  k15 run S GTOP caps
 * env:   CUT (bit mask), LO, PART NPARTS DEPTH (run: only the prefixes of DEPTH rows with index = PART mod NPARTS)
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>
#include <time.h>

#ifndef NSYM
#define NSYM 7
#endif
#define K NSYM
#if NSYM == 7
#define NP 5040
#define NC 720
#define NY 840
#elif NSYM == 6
#define NP 720
#define NC 120
#define NY 144
#elif NSYM == 5
#define NP 120
#define NC 24
#define NY 30
#else
#error NSYM must be 5, 6 or 7
#endif
#define L (K - 1)
#define INF 1000000
static int8_t PERM[NP][8];
static int *RK;
static int16_t SIG[NP], SIGI[NP], T2[NP], CLS[NP], CYC[NP];
static int16_t succ3[NP][8], succ4[NP][32];
static int nsucc3[NP], nsucc4[NP];
static int16_t CC[NC][K];      /* the 7 two-cycles through a class */
static int16_t YC[NY][L];      /* the 6 classes of a two-cycle */

static int code(const int8_t *w) { int c = 0; for (int i = 0; i < K; i++) c = c * K + w[i]; return c; }
static int ewf(int u, int v) {
    for (int t = 1; t < K; t++) { int ok = 1; for (int i = 0; i + t < K; i++) if (PERM[u][i + t] != PERM[v][i]) { ok = 0; break; } if (ok) return t; }
    return K;
}
static void build(void) {
    int pw = 1; for (int i = 0; i < K; i++) pw *= K;
    RK = (int *)malloc(sizeof(int) * pw); for (int i = 0; i < pw; i++) RK[i] = -1;
    int8_t w[8]; for (int i = 0; i < K; i++) w[i] = (int8_t)i;
    int cnt = 0;
    for (;;) {
        memcpy(PERM[cnt], w, K); RK[code(w)] = cnt; cnt++;
        int i = K - 2; while (i >= 0 && w[i] > w[i + 1]) i--;
        if (i < 0) break;
        int j = K - 1; while (w[j] < w[i]) j--;
        int8_t t = w[i]; w[i] = w[j]; w[j] = t;
        for (int a = i + 1, b = K - 1; a < b; a++, b--) { t = w[a]; w[a] = w[b]; w[b] = t; }
    }
    for (int p = 0; p < NP; p++) {
        int8_t v[8];
        for (int i = 0; i < K - 1; i++) v[i] = PERM[p][i + 1]; v[K - 1] = PERM[p][0];
        SIG[p] = (int16_t)RK[code(v)];
        for (int i = 0; i < K - 2; i++) v[i] = PERM[p][i + 1]; v[K - 2] = PERM[p][0]; v[K - 1] = PERM[p][K - 1];
        T2[p] = (int16_t)RK[code(v)];
    }
    for (int p = 0; p < NP; p++) SIGI[SIG[p]] = (int16_t)p;
    for (int p = 0; p < NP; p++) CLS[p] = -1;
    int nc = 0;
    for (int p = 0; p < NP; p++) if (CLS[p] < 0) { int x = p; do { CLS[x] = (int16_t)nc; x = SIG[x]; } while (x != p); nc++; }
    for (int p = 0; p < NP; p++) CYC[p] = -1;
    int ny = 0;
    for (int p = 0; p < NP; p++) if (CYC[p] < 0) { int x = p, i = 0; do { CYC[x] = (int16_t)ny; YC[ny][i++] = CLS[x]; x = T2[x]; } while (x != p); if (i != L) exit(9); ny++; }
    if (nc != NC || ny != NY) { fprintf(stderr, "geometry\n"); exit(9); }
    { int fill[NC]; memset(fill, 0, sizeof fill);
      for (int p = 0; p < NP; p++) { int c = CLS[p]; CC[c][fill[c]++] = CYC[p]; }
      for (int c = 0; c < NC; c++) { if (fill[c] != K) exit(9); for (int i = 0; i < K; i++) for (int j = 0; j < i; j++) if (CC[c][i] == CC[c][j]) exit(9); } }
    for (int q = 0; q < NP; q++) {
        int u = SIGI[q]; nsucc3[q] = nsucc4[q] = 0;
        for (int v = 0; v < NP; v++) {
            if (CLS[v] == CLS[q]) continue;
            int e = ewf(u, v);
            if (e == 3) succ3[q][nsucc3[q]++] = (int16_t)v;
            if (e == 4) succ4[q][nsucc4[q]++] = (int16_t)v;
        }
    }
}

#define SM 12
#define GM 128
#define RM 256
static int P[SM][400];
static int TS, GTOP, G, LO = -1, CUT = 0;
static uint8_t keepN[SM][GM][RM], keepS[SM][GM][RM];
static int16_t phiN[SM][GM][RM], phiS[SM][GM][RM];   /* least Phi that keeps (only with CUT) */
static int POTA = 2, POTB = 3, POTH = 5;   /* potential of a cut: POTA rows - POTB holes - 2 POTH (links of weight 4 before the cut) - POTH [the cut link has weight 4] */
static int16_t revA1[SM][GM][RM], revA2[SM][GM][RM];   /* CUT bit 4 (Lemma REV): keep iff M + m >= A1 or m >= A2 */

static void readcaps(const char *fn) {
    for (int s = 0; s < SM; s++) for (int i = 0; i < 400; i++) P[s][i] = INF;
    FILE *f = fopen(fn, "r"); if (!f) { fprintf(stderr, "no caps file %s\n", fn); exit(1); }
    char *line = (char *)malloc(1 << 16);
    while (fgets(line, 1 << 16, f)) {
        char *p = strchr(line, ':'); if (!p || line[0] == '#') continue;
        int t = atoi(line), i = 0; p++;
        if (t < 0 || t >= SM) continue;
        char *tok = strtok(p, " \t\r\n");
        while (tok && i < 400) { P[t][i++] = atoi(tok); tok = strtok(NULL, " \t\r\n"); }
    }
    fclose(f);
}
static void tables(void) {
    G = GTOP - L * TS;
    if (G >= GM) exit(2);
    for (int s = 0; s <= TS; s++) for (int x = 0; x <= G; x++) if (P[s][x] >= INF) { fprintf(stderr, "caps row %d does not reach %d\n", s, G); exit(1); }
    for (int t = 0; t <= TS; t++) for (int d = 0; d < GM; d++) for (int r = 0; r < RM; r++) {
        int a = 0, b = 0, pa = INF, pb = INF;
        for (int x = d > LO ? d : LO + 1; x <= G; x++) {
            int need = P[TS][x] - r - (x - d) + 1;     /* Phi >= need  <=>  r + (x-d) + Phi > P_S(x) */
            if (r + P[TS - t][x - d] > P[TS][x]) { a = 1; if (need < pa) pa = need; }
            if (t < TS && r + P[TS - t - 1][x - d] > P[TS][x]) { b = 1; if (need < pb) pb = need; }
        }
        keepN[t][d][r] = (uint8_t)a; keepS[t][d][r] = (uint8_t)b;
        phiN[t][d][r] = (int16_t)(a ? (pa < -30000 ? -30000 : pa) : 30000);
        phiS[t][d][r] = (int16_t)(b ? (pb < -30000 ? -30000 : pb) : 30000);
        /* Lemma REV: potential f = POTA rows - POTB holes; c(x) = least f of a counterexample at level x;
           rise(E) = most that a later segment with at most E holes can add */
        int a1 = 30000, a2 = 30000, f = POTA * r - POTB * d - 2 * POTH * t;
        int rise = 0;
        for (int x = d; x <= G; x++) {
            for (int sB = 0; sB <= TS - t; sB++) { int v = POTA * P[sB][x - d] - POTB * (x - d) - 2 * POTH * sB; if (v > rise) rise = v; }
            if (x <= LO) continue;
            int ok = (r + P[TS - t][x - d] > P[TS][x]) || (t < TS && r + P[TS - t - 1][x - d] > P[TS][x]);
            if (!ok) continue;
            int c = POTA * (P[TS][x] + 1) - POTB * x - 2 * POTH * TS;
            if (c < a1) a1 = c;
            if (!(CUT & 8)) { if (c - f - rise < a2) a2 = c - f - rise; }
            else {
                /* the peak is a proper prefix with d' holes, d <= d' <= x, and t' >= t links: its potential is at most
                   U(d') = max_t' (POTA P_t'(d') - POTB d') and at most f + seg(d' - d) */
                int best = -30000;
                for (int d2 = d; d2 <= x; d2++) {
                    int U = -30000, sg = -30000;
                    for (int t2 = t; t2 <= TS; t2++) { int v = POTA * P[t2][d2] - POTB * d2 - 2 * POTH * t2; if (v > U) U = v; }
                    for (int sB = 0; sB <= TS - t; sB++) { int v = POTA * P[sB][d2 - d] - POTB * (d2 - d) - 2 * POTH * sB; if (v > sg) sg = v; }
                    int pk = f + sg < U ? f + sg : U;
                    if (pk > best) best = pk;
                }
                if (c - best < a2) a2 = c - best;
            }
        }
        revA1[t][d][r] = (int16_t)(a1 < -30000 ? -30000 : a1); revA2[t][d][r] = (int16_t)(a2 < -30000 ? -30000 : a2);
    }
}


/* ------------------------------------------------ exact search (flat) ------------------------------------------------ */
typedef struct { int16_t A1, A2; uint8_t kN, kS, pad[2]; } Rule;
static Rule RULE[SM][GM][RM];
static int16_t ROWC[NP][6], ROWE[NP][6];
static uint8_t IM[SM + 1][GM][RM + 1];   /* bit k: a row with k holes after a prefix with d holes gives a prefix (t, d + k, r1) that is a violation or kept by the tables */
static uint8_t used[NC];
static long long nodes, kept, viol, fcount, cutR, nodes_top, kept_top;
static int PARTI = 0, NPARTS = 1, DEPTH = 0, STOP = 0;
static int JS = 0; static int16_t J3[NP], J4[NP]; static long long jsref;
/* Rule JS.  q = last entry of a row with at most 5 blocks.  J3[q] (J4[q]) is the one successor of weight 3 (4) of the exit
   of q that lies in the class of tau2 q, the next block of that row.  A row that starts there may have one block only. */
static void js_init(void) {
    for (int q = 0; q < NP; q++) {
        int nb = T2[q], cn = CLS[nb], n3 = 0, n4 = 0; J3[q] = J4[q] = -1;
        for (int i = 0; i < nsucc3[q]; i++) if (CLS[succ3[q][i]] == cn) { J3[q] = succ3[q][i]; n3++; }
        for (int i = 0; i < nsucc4[q]; i++) if (CLS[succ4[q][i]] == cn) { J4[q] = succ4[q][i]; n4++; }
        if (n3 != 1 || n4 != 1) { fprintf(stderr, "JS: junction successors\n"); exit(9); }
        /* Lemma JS1: after the row is extended by nb, the link to tau2 of the junction successor has the same weight */
        if (ewf(SIGI[nb], T2[J3[q]]) != 3 || ewf(SIGI[nb], T2[J4[q]]) != 4 || CLS[T2[J3[q]]] == cn || CLS[T2[J4[q]]] == cn) { fprintf(stderr, "JS1 fails\n"); exit(9); }
    }
}


static void rows(int st, int r1, int d, int t, int m, int M, unsigned mk, int js) {
    const int16_t *rc = ROWC[st];
    int len = 0;
    while (len < L && !used[rc[len]]) len++;
    if (js && len > 1) { len = 1; jsref++; }
    if (!(mk >> (L - len))) return;            /* no row of length <= len matters (len = 0: mk >> 6 = 0) */
    const int f0 = POTA * r1 - 2 * POTH * t;
    const int rr = r1 < RM ? r1 : RM - 1;
    int l;
    for (l = 1; l <= len; l++) {
        used[rc[l - 1]] = 1;
        int k = L - l, dd = d + k;
        if (!((mk >> k) & 1)) continue;
        nodes++;
        if (t == TS && dd > LO && r1 > P[TS][dd]) {
            viol++;
            if (viol <= 20) { printf("VIOLATION: sequence with %d rows, %d holes, %d links of weight 4 (cap %d)\n", r1, dd, t, P[TS][dd]); fflush(stdout); }
            if (STOP) { printf("stopped at the first violation after %lld rows placed, %lld kept\n", nodes, kept); fflush(stdout); exit(0); }
            continue;
        }
        if (r1 == DEPTH) { if (NPARTS > 1 && (fcount++ % NPARTS) != PARTI) continue; }
        const Rule *ru = &RULE[t][dd][rr];
        int a = ru->kN, b = ru->kS;
        if (!(a | b)) continue;
        int mN = m, MN = M, mS = m, MS = M;
        if (CUT & 4) {
            int f = f0 - POTB * dd, g = f - POTH, A1 = ru->A1, A2 = ru->A2;
            if (f < mN) mN = f;
            if (f > MN) MN = f;
            if (g < mS) mS = g;
            if (g > MS) MS = g;
            if (a && mN < 0 && !(MN + mN >= A1 || mN >= A2)) { a = 0; cutR++; }
            if (b && mS < 0 && !(MS + mS >= A1 || mS >= A2)) { b = 0; cutR++; }
            if (!(a | b)) continue;
        }
        kept++;
        int x = ROWE[st][l - 1];
        unsigned mkN = IM[t][dd][rr + 1], mkS = IM[t + 1][dd][rr + 1];
        if (a && mkN) for (int i = 0; i < nsucc3[x]; i++) rows(succ3[x][i], r1 + 1, dd, t, mN, MN, mkN, JS && l < L && succ3[x][i] == J3[x]);
        if (b && mkS) for (int i = 0; i < nsucc4[x]; i++) rows(succ4[x][i], r1 + 1, dd, t + 1, mS, MS, mkS, JS && l < L && succ4[x][i] == J4[x]);
    }
    while (len > 0) used[rc[--len]] = 0;
}
/* nodes_top / kept_top: the counters as they stood when the last prefix of DEPTH rows was reached do not separate the
   top of the tree exactly; the exact split is done by a second pass with the gate closed (PARTI = -1). */
static void mode_run(void) {
    for (int p = 0; p < NP; p++) { int x = p; for (int i = 0; i < 6; i++) { ROWE[p][i] = (int16_t)x; ROWC[p][i] = CLS[x]; x = T2[x]; } }
    for (int t = 0; t <= TS; t++) for (int d = 0; d < GM; d++) for (int r = 0; r < RM; r++) {
        Rule *ru = &RULE[t][d][r];
        ru->kN = keepN[t][d][r]; ru->kS = keepS[t][d][r]; ru->A1 = revA1[t][d][r]; ru->A2 = revA2[t][d][r];
    }
    if (RM < 250) exit(9);
    memset(IM, 0, sizeof IM);
    for (int t = 0; t <= TS; t++) for (int d = 0; d < GM; d++) for (int r = 0; r < RM; r++) {
        unsigned mk = 0;
        for (int k = 0; k < L; k++) {
            int dd = d + k; if (dd > G) continue;
            if ((t == TS && dd > LO && r > P[TS][dd]) || keepN[t][dd][r] || keepS[t][dd][r]) mk |= 1u << k;
        }
        IM[t][d][r] = (uint8_t)mk;
    }
    for (int t = 0; t <= TS; t++) for (int d = 0; d < GM; d++) IM[t][d][RM] = IM[t][d][RM - 1];
    long long top_nodes = 0, top_kept = 0;
    if (NPARTS > 1) {            /* the top of the tree alone: gate closed for every prefix of DEPTH rows */
        int sp = PARTI; PARTI = -1;
        memset(used, 0, sizeof used); rows(0, 1, 0, 0, 0, 0, (1 << L) - 1, 0);
        top_nodes = nodes; top_kept = kept; PARTI = sp;
        if (viol) { printf("violation above the gate\n"); }
        nodes = kept = fcount = cutR = 0;
    }
    memset(used, 0, sizeof used);
    clock_t t0 = clock();
    rows(0, 1, 0, 0, 0, 0, (1 << L) - 1, 0);
    double sec = (double)(clock() - t0) / CLOCKS_PER_SEC;
    printf("run S=%d GTOP=%d (holes <= %d) LO=%d CUT=%d POT=%d,%d,%d part %d of %d at depth %d: violations %lld   rows placed %lld   kept %lld   above the gate: rows placed %lld kept %lld   prefixes at the gate %lld   time %.1fs  (%.4f us per kept)\n",
           TS, GTOP, G, LO, CUT, POTA, POTB, POTH, PARTI, NPARTS, DEPTH, viol, nodes, kept, top_nodes, top_kept, fcount, sec, kept ? 1e6 * sec / kept : 0);
}

int main(int argc, char **argv) {
    if (argc < 5) { fprintf(stderr, "usage: kfast run S GTOP caps\n"); return 2; }
    if (getenv("CUT")) CUT = atoi(getenv("CUT"));
    if (getenv("LO")) LO = atoi(getenv("LO"));
    if (getenv("POTA")) POTA = atoi(getenv("POTA"));
    if (getenv("POTB")) POTB = atoi(getenv("POTB"));
    if (getenv("POTH")) POTH = atoi(getenv("POTH"));
    if (getenv("STOP")) STOP = atoi(getenv("STOP"));
    if (getenv("JS")) JS = atoi(getenv("JS"));
    if (getenv("PART")) PARTI = atoi(getenv("PART"));
    if (getenv("NPARTS")) NPARTS = atoi(getenv("NPARTS"));
    if (getenv("DEPTH")) DEPTH = atoi(getenv("DEPTH"));
    TS = atoi(argv[2]); GTOP = atoi(argv[3]); readcaps(argv[4]);
    build(); tables(); js_init();
    if (!strcmp(argv[1], "run")) mode_run();
    if (JS) printf("JS=%d: rows limited to one block at %lld junction successors\n", JS, jsref);
    fflush(stdout);
    return 0;
}
